'use strict';
// Original SVG puppets. A roster controls appearance; an independent state machine
// controls each cat. The renderer intentionally caps visible cats at two.
const CAT_ROSTER=[{id:'miso',name:'Miso',coat:'#bca48c',accent:'#8c7561'},{id:'mochi',name:'Mochi',coat:'#a6b19a',accent:'#7a8e74'},{id:'nori',name:'Nori',coat:'#858680',accent:'#62665e'},{id:'chai',name:'Chai',coat:'#ccab88',accent:'#a37a58'}];
let catFrame=0,lastCatFrame=0,catActors=[],catSignature='';
const motionRandom=(lo,hi)=>lo+Math.random()*(hi-lo);
function catBehaviorFor(mood){const choices=mood<3?['sleep','sleep','idle','groom','stretch','knead']:mood===5?['walk','chase','pounce','groom','stretch','sit','roll','jump','shake','yawn','loaf']:['walk','groom','sit','stretch','sleep','knead','yawn','loaf','jump'];return choices[Math.floor(Math.random()*choices.length)];}
function catBounds(index,width,catWidth,count){const section=width/count;return {min:index*section+2,max:Math.max(index*section+3,(index+1)*section-catWidth-2)};}
function setCatBehavior(actor,behavior,now){actor.normalSpeed??=actor.speed;actor.speed=behavior==='chase'?43:actor.normalSpeed;actor.behavior=behavior;actor.el.dataset.behavior=behavior;actor.el.dataset.state=['sleep','nuzzle','knead','loaf','yawn'].includes(behavior)?'rest':'curious';actor.until=now+motionRandom(4200,8500);actor.el.querySelectorAll('.leg').forEach(leg=>leg.style.transform='');actor.el.querySelector('.cat-rig').style.transform='';if(['walk','chase'].includes(behavior)){const stage=actor.el.parentElement,range=catBounds(actor.index,stage.clientWidth,actor.el.clientWidth,catActors.length);actor.target=actor.x<(range.min+range.max)/2?range.max:range.min;actor.direction=actor.target>=actor.x?1:-1;actor.el.style.setProperty('--direction',actor.direction);actor.until=now+Math.abs(actor.target-actor.x)/actor.speed*1000+200;}}
function tickCatActors(now){const dt=Math.min((now-lastCatFrame)/1000||0,.045);lastCatFrame=now;if(!reducedCats()&&!document.hidden){for(const actor of catActors){if(!actor.el.isConnected)continue;if(now>=actor.until&&!actor.hover){setCatBehavior(actor,catBehaviorFor(selectedMood||state.moods.at(-1)?.value||3),now);}if(['walk','chase'].includes(actor.behavior)){const distance=actor.target-actor.x,step=Math.sign(distance)*Math.min(Math.abs(distance),actor.speed*dt);actor.x+=step;actor.phase+=Math.abs(step)/Math.max(actor.el.clientWidth*.23,12)*Math.PI*2;actor.el.style.setProperty('--x',actor.x+'px');const angle=Math.sin(actor.phase)*17;for(const [selector,sign] of [['.leg-front',1],['.leg-near-back',1],['.leg-back',-1],['.leg-near-front',-1]])actor.el.querySelector(selector).style.transform='rotate('+angle*sign+'deg)';actor.el.querySelector('.cat-rig').style.transform='translateY('+(-Math.abs(Math.sin(actor.phase))*1.3)+'px)';if(Math.abs(distance)<.5)setCatBehavior(actor,'sit',now);}}}catFrame=requestAnimationFrame(tickCatActors);}
renderCats=function(){clearInterval(catLoop);const mood=selectedMood||state.moods.at(-1)?.value||3,count=Math.max(1,Math.min(2,Number(prefs().catCount)||2)),signature=[mood,count,catsHidden,reducedCats()].join(':');if(signature===catSignature&&$('#cat-shelf .cat-stage'))return;catSignature=signature;cancelAnimationFrame(catFrame);let shelf=$('#cat-shelf');if(!shelf){shelf=document.createElement('div');shelf.id='cat-shelf';document.body.append(shelf);}catActors=[];if(catsHidden){shelf.className='';shelf.innerHTML='<button class="cat-restore" data-cats="show" aria-label="Show decorative cats">'+catSymbol()+'</button>';return;}shelf.className='cat-shelf living-cats fluid-cats';shelf.innerHTML=`<div class="cat-stage" data-count="${count}">${CAT_ROSTER.slice(0,count).map((cat,i)=>`<button class="cat-button living-cat" data-cat="${cat.name}" data-behavior="${mood<3?'sleep':i?'groom':'sit'}" data-state="${mood<3?'rest':'curious'}" aria-label="Pet ${cat.name}" style="--x:${i?165:20}px;--direction:${i?-1:1}">${catArt(cat.coat,cat.accent)}</button>`).join('')}</div><details class="cat-options"><summary aria-label="Cat controls">···</summary><button data-cats="pause">${document.body.classList.contains('cats-paused')?'Resume':'Pause'}</button><button data-cats="play">Play</button><button data-cats="hide">Hide</button></details>`;shelf.querySelectorAll('.living-cat').forEach((el,index)=>{const actor={el,index,x:index?165:20,target:0,direction:index?-1:1,speed:motionRandom(22,29),phase:0,until:performance.now()+motionRandom(1500,4200),behavior:mood<3?'sleep':index?'groom':'sit',hover:false};catActors.push(actor);el.addEventListener('pointerenter',()=>{if(reducedCats())return;actor.hover=true;el.dataset.petting='yes';setCatBehavior(actor,'nuzzle',performance.now());});el.addEventListener('pointerleave',()=>{actor.hover=false;el.dataset.petting='no';setCatBehavior(actor,'sit',performance.now());});el.addEventListener('click',()=>{actor.hover=false;el.dataset.petting='yes';setCatBehavior(actor,'nuzzle',performance.now());actor.until=performance.now()+2400;});});lastCatFrame=performance.now();if(!reducedCats())catFrame=requestAnimationFrame(tickCatActors);};
// Switch pages with a small fade and lift, but do not animate each AI message.
const transitionRoute=route;let lastTransitionHash='';
route=function(){transitionRoute();const hash=location.hash;if(hash!==lastTransitionHash&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){$('#main').animate([{opacity:.2,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:320,easing:'cubic-bezier(.2,.7,.3,1)'});lastTransitionHash=hash;}};
route();
